Here is the `processPayload` function with full JSDoc documentation:

```typescript
/**
 * Validates and transforms an incoming API payload into a normalized structure.
 *
 * The function performs three stages of processing:
 *  1. Guard — rejects null/undefined and non-object values immediately.
 *  2. Sanitization — strips unknown keys, coerces types, and applies defaults.
 *  3. Validation — returns a discriminated union so callers can inspect errors.
 *
 * @param data - The raw, untrusted input received from the API layer.  Must be
 *               an unknown type; the function narrows it internally.
 * @returns A result object.  On success the `ok` property is `true` and the
 *          `value` property holds the normalized {@link NormalizedPayload}.
 *          On failure `ok` is `false` and `errors` contains a human-readable
 *          message for each field that failed validation.
 *
 * @example
 * ```ts
 * const result = processPayload({ name: "  Alice ", age: "30" });
 * if (result.ok) {
 *   console.log(result.value); // { name: "Alice", age: 30 }
 * } else {
 *   result.errors.forEach(e => console.error(e.field, e.message));
 * }
 * ```
 */
function processPayload(data: unknown): ProcessResult {
    // -- Stage 1: Structural guard ------------------------------------------------
    if (data === null || data === undefined) {
        return {
            ok: false,
            errors: [{ field: "root", message: "Payload must not be null or undefined." }],
        };
    }

    if (typeof data !== "object" || Array.isArray(data)) {
        return {
            ok: false,
            errors: [{ field: "root", message: "Payload must be a plain object, not an array or primitive." }],
        };
    }

    const raw = data as Record<string, unknown>;
    const errors: FieldError[] = [];

    // -- Stage 2: Extract and coerce known fields ---------------------------------

    const name = coerceTrimmedString(raw, "name", errors);         // required
    const age = coercePositiveInteger(raw, "age", errors);         // required
    const email = coerceTrimmedString(raw, "email", errors, true); // optional

    // -- Stage 3: Return result ---------------------------------------------------
    if (errors.length > 0) {
        return { ok: false, errors };
    }

    return {
        ok: true,
        value: { name: name!, age: age!, email },
    };
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** A single field-level validation error. */
interface FieldError {
    /** The dot-notation path to the field (e.g. "name" or "address.city"). */
    field: string;
    /** A clear, action-oriented description of what is wrong. */
    message: string;
}

/** The payload shape returned on successful validation. */
interface NormalizedPayload {
    /** The user's display name, trimmed of leading and trailing whitespace. */
    name: string;
    /** The user's age as a positive integer. */
    age: number;
    /** Optional contact email, trimmed.  `undefined` when omitted or empty. */
    email?: string;
}

/** Discriminated result: either a valid payload or a list of field errors. */
type ProcessResult =
    | { ok: true; value: NormalizedPayload }
    | { ok: false; errors: FieldError[] };

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Extracts a trimmed string from the raw object.  Records an error when the
 * field is missing, not a string, or (if required) is empty after trimming.
 *
 * @param field - Key in the raw payload.
 * @param required - When `false`, missing/empty fields return `undefined`
 *                   without recording an error.
 */
function coerceTrimmedString(
    raw: Record<string, unknown>,
    field: string,
    errors: FieldError[],
    required: boolean = true,
): string | undefined {
    const value = raw[field];

    if (value === undefined || value === null) {
        if (required) {
            errors.push({ field, message: `Field "${field}" is required and must be a non-empty string.` });
        }
        return undefined;
    }

    if (typeof value !== "string") {
        errors.push({ field, message: `Field "${field}" must be a string; received ${typeof value}.` });
        return undefined;
    }

    const trimmed = value.trim();

    if (required && trimmed.length === 0) {
        errors.push({ field, message: `Field "${field}" must not be empty.` });
        return undefined;
    }

    return trimmed;
}

/**
 * Extracts and coerces a positive integer from the raw object.  Accepts numeric
 * strings (e.g. `"30"`) but rejects floats, zero, and negative values.
 */
function coercePositiveInteger(
    raw: Record<string, unknown>,
    field: string,
    errors: FieldError[],
): number | undefined {
    const value = raw[field];

    if (value === undefined || value === null) {
        errors.push({ field, message: `Field "${field}" is required.` });
        return undefined;
    }

    if (typeof value === "number") {
        if (!Number.isFinite(value) || !Number.isInteger(value) || value <= 0) {
            errors.push({ field, message: `Field "${field}" must be a positive integer.` });
            return undefined;
        }
        return value;
    }

    if (typeof value === "string") {
        const parsed = Number(value);
        if (value.trim() === "" || !Number.isFinite(parsed) || !Number.isInteger(parsed) || parsed <= 0) {
            errors.push({ field, message: `Field "${field}" must be a positive integer; received "${value}".` });
            return undefined;
        }
        return parsed;
    }

    errors.push({ field, message: `Field "${field}" must be a number or numeric string; received ${typeof value}.` });
    return undefined;
}
```

**Key design decisions:**

- **Return type is a discriminated union** — callers check `result.ok` and TypeScript narrows to either `result.value` or `result.errors` automatically. No try/catch required.
- **Errors accumulate** — the function validates all fields before returning, so the consumer sees every problem in one round-trip instead of fixing errors one at a time.
- **Active-voice messages** — every error tells the caller exactly what went wrong (`"Field 'age' must be a positive integer"`) rather than stating what the system did.
- **Coercion is explicit** — string-to-number coercion is intentional and documented; unknown keys in the input object are silently dropped rather than passed through.
- **Helpers are pure** — `coerceTrimmedString` and `coercePositiveInteger` accept the shared `errors` array and push into it, keeping the main function free of repetitive branching.

```js
/**
 * Reads user data from the API for a given user ID.
 *
 * @async
 * @param {string|number} userId - Unique identifier of the user to read.
 * @returns {Promise<Object>} Resolves with the user data object when the API
 *   returns a successful response.
 *
 * @throws {TypeError} The `userId` argument is missing, null, or not a
 *   string or number.
 * @throws {RangeError} The `userId` argument is an empty string after
 *   trimming whitespace.
 * @throws {Error} The network request fails (DNS resolution failure,
 *   connection refused, or timeout). The original cause attaches as
 *   `error.cause`.
 * @throws {Error} The API responds with an HTTP status outside the 2xx
 *   range (4xx client error or 5xx server error). The error message
 *   includes the status code and status text; `error.status` carries the
 *   numeric status code, and `error.body` carries the raw response body
 *   string when available.
 * @throws {SyntaxError} The API response body is not valid JSON.
 */
async function fetchUserData(userId) {
  if (userId == null) {
    throw new TypeError(
      "userId is required and must be a string or number, received " +
        typeof userId
    );
  }

  const coerced = String(userId).trim();
  if (coerced === "") {
    throw new RangeError("userId must not be an empty string");
  }

  let response;
  try {
    response = await fetch(`https://api.example.com/users/${coerced}`, {
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(10_000),
    });
  } catch (cause) {
    throw new Error("Network request failed", { cause });
  }

  if (!response.ok) {
    const error = new Error(
      `API returned ${response.status} ${response.statusText}`
    );
    error.status = response.status;
    try {
      error.body = await response.text();
    } catch {
      // Body read failed; continue without it.
    }
    throw error;
  }

  let data;
  try {
    data = await response.json();
  } catch (cause) {
    throw new SyntaxError("API response body is not valid JSON", { cause });
  }

  return data;
}
```
